<?php

namespace App\Support;

/**
 * The console's workflow-preset catalogue for this runtime.
 *
 * WordPress builds the catalogue in PHP
 * (`WP_MCP_AI_Pro_Workflow_Presets`); this runtime loads the same data from
 * `resources/workflow-presets.json`, generated by
 * `bin/generate-laravel-workflow-presets.php`. The file is the export, not a
 * hand-maintained copy — regenerate it rather than editing it.
 *
 * No filtering happens here. The canvas maps any node `type` onto a generic
 * node and round-trips the original through `data.rawType`
 * (`spa-v2/src/features/workflows/workflow-graph.ts`), so every preset is
 * representable even when its tools are not yet ported. Execution is what
 * depends on the registry, and that gate lives in the executor (090-h H3).
 *
 * **Licence.** The data file is Pro-licensed content (see its `_license`
 * field); this loader and the rest of the app are MIT. The two travel
 * together but are licensed separately, the same split the repo already makes
 * between the base plugin and `addons/pro`. Replace the source catalogue if a
 * deployment needs an MIT-only preset set.
 */
final class WorkflowPresets
{
    /**
     * Parsed catalogue, or null before the first read.
     *
     * @var array{categories: array<string, string>, presets: array<string, array<string, mixed>>}|null
     */
    private static ?array $catalogue = null;

    /**
     * Category slug => label, exactly as WordPress serves it.
     *
     * @return array<string, string>
     */
    public static function categories(): array
    {
        return self::catalogue()['categories'];
    }

    /**
     * Preset id => full definition (name, description, category, icon, tags,
     * nodes, edges).
     *
     * @return array<string, array<string, mixed>>
     */
    public static function all(): array
    {
        return self::catalogue()['presets'];
    }

    /**
     * One preset by id, or null.
     *
     * @return array<string, mixed>|null
     */
    public static function find(string $id): ?array
    {
        $presets = self::all();

        return $presets[$id] ?? null;
    }

    /**
     * Summaries for the console's preset table — graphs stripped, matching
     * `WP_MCP_AI_Pro_Workflow_Presets_REST_Controller::list_presets()`.
     *
     * @return list<array{id: string, name: string, description: string, category: string, icon: string, tags: list<string>}>
     */
    public static function summaries(): array
    {
        $summaries = [];

        foreach (self::all() as $id => $preset) {
            $summaries[] = [
                'id' => (string) $id,
                'name' => (string) ($preset['name'] ?? ''),
                'description' => (string) ($preset['description'] ?? ''),
                'category' => (string) ($preset['category'] ?? ''),
                'icon' => (string) ($preset['icon'] ?? ''),
                'tags' => array_values(array_map('strval', (array) ($preset['tags'] ?? []))),
            ];
        }

        return $summaries;
    }

    /**
     * Load the JSON export once per request/process.
     *
     * A missing or unreadable file is a deployment fault, not a user error,
     * so it surfaces as an empty catalogue — the console renders "No presets
     * available" instead of a stack trace. The file is checked into the repo,
     * so this only happens on a broken image.
     *
     * @return array{categories: array<string, string>, presets: array<string, array<string, mixed>>}
     */
    private static function catalogue(): array
    {
        if (null !== self::$catalogue) {
            return self::$catalogue;
        }

        $empty = ['categories' => [], 'presets' => []];
        $path = resource_path('workflow-presets.json');

        if (! is_readable($path)) {
            self::$catalogue = $empty;

            return self::$catalogue;
        }

        $raw = file_get_contents($path); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents -- local resource, not remote.
        $decoded = is_string($raw) ? json_decode($raw, true) : null;

        if (! is_array($decoded)) {
            self::$catalogue = $empty;

            return self::$catalogue;
        }

        $categories = [];
        foreach ((array) ($decoded['categories'] ?? []) as $slug => $label) {
            $categories[(string) $slug] = (string) $label;
        }

        $presets = [];
        foreach ((array) ($decoded['presets'] ?? []) as $id => $preset) {
            if (! is_array($preset)) {
                continue;
            }

            $presets[(string) $id] = $preset;
        }

        self::$catalogue = ['categories' => $categories, 'presets' => $presets];

        return self::$catalogue;
    }

    /**
     * Test seam — drop the parsed catalogue.
     */
    public static function flush(): void
    {
        self::$catalogue = null;
    }
}
